// Stable IDs live in protocol/names.json. Never renumber existing entries.
// Generated files are checked in; building the library does not require Node.
import fs from 'node:fs';

const dictionary = JSON.parse(fs.readFileSync(new URL('./protocol/names.json', import.meta.url)));
const preamble = `/* Generated by stomptalkgen.js; edit protocol/names.json. */
#pragma once

#include "name_group.hpp"

namespace stomptalk {
namespace detail {
namespace {

// TU-local tags keep baseline and AVX2 template instantiations distinct.
`;

for (const [kind, entries] of [['method', dictionary.methods], ['header', dictionary.headers]])
{
    let classifiers = preamble;
    const upper = kind.toUpperCase();
    const width = kind === 'method' ? 64 : 32;
    const names = new Set();
    const ids = new Set();
    const wires = new Set();

    for (const entry of entries)
    {
        if (!Number.isSafeInteger(entry.id) || entry.id <= 0 || entry.id >= 0xffffffff ||
            !/^[A-Z][A-Z0-9_]*$/.test(entry.name) || !entry.wire.length ||
            names.has(entry.name) || ids.has(entry.id) || wires.has(entry.wire))
            throw new Error('invalid dictionary');
        names.add(entry.name);
        ids.add(entry.id);
        wires.add(entry.wire);
    }

    let header = `/* Generated by stomptalkgen.js; edit protocol/names.json. */
#ifndef STOMPTALK_${upper}_H
#define STOMPTALK_${upper}_H

#include "stomptalk/type.h"

typedef uint${width}_t stomptalk_${kind}_id;

#define STOMPTALK_${upper}_NONE UINT${width}_C(0)
#define STOMPTALK_${upper}_UNKNOWN UINT${width}_MAX
`;
    for (const entry of entries)
        header += `#define STOMPTALK_${upper}_${entry.name} UINT${width}_C(${entry.id})\n`;
    header += '\n#endif\n';
    fs.writeFileSync(new URL(`./include/stomptalk/${kind}.h`, import.meta.url), header);

    classifiers += `namespace ${kind} {\n\n`;
    for (const entry of entries)
    {
        classifiers += `struct ${entry.name.toLowerCase()}
    : name_entry<stomptalk_${kind}_id, STOMPTALK_${upper}_${entry.name}>
{
    STOMPTALK_FORCE_INLINE
    static constexpr stomptalk_view text() noexcept
    {
        return name_view(${JSON.stringify(entry.wire)});
    }
};

`;
    }
    classifiers += `} // namespace ${kind}\n\n`;

    const lengths = [...new Set(entries.map(entry => Buffer.byteLength(entry.wire)))].sort((a, b) => a - b);
    for (const length of lengths)
    {
        const group = entries.filter(entry => Buffer.byteLength(entry.wire) === length);
        const tags = group.map(entry => `${kind}::${entry.name.toLowerCase()}`);
        classifiers += `using ${kind}s_${length} = name_group<\n    ${tags.join(',\n    ')}>;\n\n`;
    }

    classifiers += `template<class Backend = backend::swar>
STOMPTALK_FORCE_INLINE
stomptalk_${kind}_id detect_${kind}(stomptalk_view name) noexcept
{
    assert(name.data || !name.size);

    switch (name.size)
    {
`;
    for (const length of lengths)
        classifiers += `    case ${kind}s_${length}::size:\n        return ${kind}s_${length}::find<Backend>(name.data);\n`;
    classifiers += `    default:;\n    }\n\n    return STOMPTALK_${upper}_UNKNOWN;\n}\n\n`;

    classifiers += `inline stomptalk_view ${kind}_name(stomptalk_${kind}_id id) noexcept
{
    switch (id)
    {
`;
    for (const entry of entries)
        classifiers += `    case STOMPTALK_${upper}_${entry.name}:\n        return ${kind}::${entry.name.toLowerCase()}::text();\n`;
    classifiers += '    default:;\n    }\n\n    return {nullptr, 0};\n}\n\n';
    classifiers += '} // namespace\n} // namespace detail\n} // namespace stomptalk\n';
    fs.writeFileSync(new URL(`./src/${kind}s.hpp`, import.meta.url), classifiers);
}

const length = dictionary.headers.find(entry => entry.name === 'CONTENT_LENGTH');
const lengthBytes = Buffer.from(length.wire);
if (lengthBytes.length !== 14)
    throw new Error('content-length wire comparison requires a 14-byte name');
const contentLength = `/* Generated by stomptalkgen.js; edit protocol/names.json. */
#pragma once

#include "backend/config.hpp"

namespace stomptalk {
namespace detail {
namespace backend {

// The first 16 bytes are the complete wire spelling, excluding the trailing NUL.
alignas(16) constexpr char content_length_wire[] = "\\n${length.wire}:";

} // namespace backend
} // namespace detail
} // namespace stomptalk
`;

fs.writeFileSync(new URL('./src/content_length.hpp', import.meta.url), contentLength);
